import{H as e,V as t,et as n,j as r}from"./chunks/framework.BWKSSupd.js";var i=JSON.parse(`{"title":"卸载组件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/meta/uninstall.md","filePath":"guide/meta/uninstall.md","lastUpdated":1785676849000}`),a={name:`guide/meta/uninstall.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="卸载组件" tabindex="-1">卸载组件 <a class="header-anchor" href="#卸载组件" aria-label="Permalink to “卸载组件”">​</a></h1><p>相对于单页应用，多页签框架为跨页操作带来了更好的体验，但也意味着更复杂的交互场景。如果项目不再需要 RouterTab，按以下步骤移除。</p><h2 id="一、替换命令式调用" tabindex="-1">一、替换命令式调用 <a class="header-anchor" href="#一、替换命令式调用" aria-label="Permalink to “一、替换命令式调用”">​</a></h2><p>批量查找 <code>useRouterTab()</code> 取到的实例调用，参考下表替换为原生 Vue Router：</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th><th>替换方案</th></tr></thead><tbody><tr><td><code>tabs.open</code></td><td>全新打开页签</td><td><code>router.push(path)</code></td></tr><tr><td><code>tabs.close</code></td><td>关闭页签并跳转</td><td><code>router.replace(path)</code></td></tr><tr><td><code>tabs.refresh</code> / <code>tabs.refreshAll</code> / <code>tabs.refreshTab</code></td><td>刷新页签</td><td>组件内部自行提供刷新数据的方法</td></tr><tr><td><code>tabs.reset</code></td><td>重置到默认或指定页</td><td><code>router.replace(path)</code></td></tr><tr><td><code>tabs.reload</code></td><td>重载当前视图</td><td>组件内部自行提供刷新方法</td></tr><tr><td><code>tabs.adjust</code></td><td>重算页签滚动</td><td>无需替代（页签栏本身已移除）</td></tr><tr><td><code>tabs.openIframe</code> / <code>tabs.closeIframe</code> / <code>tabs.refreshIframe</code></td><td>iframe 页签相关</td><td>自行封装 iframe 容器与操作方法</td></tr><tr><td><code>useRouterPage({ beforePageLeave })</code></td><td>页面离开确认</td><td>Vue Router 的<a href="https://router.vuejs.org/zh/guide/advanced/navigation-guards.html#%E7%BB%84%E4%BB%B6%E5%86%85%E7%9A%84%E5%AE%88%E5%8D%AB" target="_blank" rel="noreferrer">组件内守卫</a> <code>onBeforeRouteLeave</code></td></tr><tr><td><code>useRouterPage({ routeTab })</code></td><td>动态页签信息</td><td>无需替代（页签栏本身已移除）</td></tr><tr><td><code>useRouterPage({ pageScroller })</code> / <code>restoreScroll()</code></td><td>滚动位置记忆</td><td>自行用 <code>onActivated</code> / <code>onDeactivated</code> 实现，或依赖浏览器原生滚动恢复</td></tr></tbody></table><h2 id="二、去除组件" tabindex="-1">二、去除组件 <a class="header-anchor" href="#二、去除组件" aria-label="Permalink to “二、去除组件”">​</a></h2><ol><li><p>用 <code>&lt;router-view&gt;</code> 替换布局中的 <code>&lt;RouterTab&gt;</code>。</p></li><li><p>参考<a href="./../essentials/#路由配置">入门</a>反向操作，移除：</p><ul><li>入口文件里的 <code>app.use(RouterTab)</code> 与样式引入 <code>import &#39;vue-router-tab/dist/index.css&#39;</code></li><li>路由配置里注入的 <code>RouterTabRoutes</code></li><li>路由 <code>meta.routerTab</code> 里的页签配置字段（<code>title</code> / <code>key</code> / <code>keepAlive</code> 等，视业务需要决定是否保留 <code>title</code> 等字段供其他用途）</li></ul></li><li><p>移除依赖：</p><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-router-tab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><h2 id="三、调整页面交互方式" tabindex="-1">三、调整页面交互方式 <a class="header-anchor" href="#三、调整页面交互方式" aria-label="Permalink to “三、调整页面交互方式”">​</a></h2><p>改为单页方式意味着不再支持跨页操作。原来靠切换页签完成的流程，需要改造为单页内部的交互，比如：</p><ul><li>弹窗 / 抽屉：临时展示的表单、详情</li><li>路由 tab（不缓存）：仍需要 URL 区分状态，但不需要多页签管理</li><li>页面内部状态切换：不涉及路由变化的场景，用组件内部的 <code>ref</code> / <code>reactive</code> 控制展示</li></ul><p>选择哪种方式取决于原页签承载的具体业务场景，没有通用方案。</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};